from acquire import *
from concurrent.futures import ThreadPoolExecutor
S=[('atlantic-map-library','https://www.atlanticcountynj.gov/government/government-information/election-services-information/board-of-elections/ward-and-election-district-boundry-maps','Atlantic'),('capemay-gis-navigation','https://capemaycountynj.gov/806/Mapping-Service','Cape May'),('essex-west-orange-map','https://westorange.org/2002/West-Orange-Ward-District-Election-Map','Essex'),('gloucester-polling-navigation','https://gloucestercountynj.gov/194/Polling-Locations','Gloucester'),('middlesex-map-library','https://www.middlesexcountynj.gov/government/departments/department-of-community-services/board-of-elections/re-warding-and-re-districting','Middlesex'),('monmouth-freehold-map','https://freeholdboroughnj.gov/government/forms/forms-documents/maps/1954-election-district-map-revised-feb-2026/file','Monmouth'),('morris-current-board','https://www.morriscountynj.gov/Departments/Board-of-Elections','Morris'),('ocean-manchester-map','https://manchestertwp.com/wp-content/uploads/2025/04/Election-District-Map-2025.pdf','Ocean'),('somerset-polling-roster','https://www.somersetcountynj.gov/government/affiliated-agencies/election-board/polling-place-locator','Somerset'),('sussex-map-navigation','https://www.sussex.nj.us/341/Maps','Sussex'),('warren-district-navigation','https://www.warrencountyvotes.com/voter-info/find-my-district','Warren'),('salem-pennsville-map','https://elections.salemcountynj.gov/wp-content/uploads/2018/08/Pennsville.pdf','Salem'),('hudson-congressional-context','https://gis.hcnj.us/Images/2022ElectionWebMaps/Congressional/CD_8.pdf','Hudson')]
write(BASE/'derived/bounded-followup-sources.json',[{'id':id,'url':u,'county':c,'parent':'actual official-domain search result; no inferred statewide coverage'} for id,u,c in S])
with ThreadPoolExecutor(max_workers=5) as e:list(e.map(lambda j:fetch(j[0],j[1],'actual official-domain search result for '+j[2]+' election maps'),S))
for id,u,c in S:
 try:
  L=links(id)
  print(id,[x for x in L if __import__('re').search(r'\.pdf|showpublished|documentcenter|iframe|district|\.zip',x['text']+' '+x['url'],__import__('re').I)][:8])
 except Exception:pass
